describe('Element Manager - Add and Delete Elements', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
  });

  it('should add and delete elements successfully', () => {
    // Verify initial state
    cy.get('[data-testid="added-manually-button"]').should('not.exist');
    cy.get('[data-testid="added-manually-button"]').should('be.visible');

    // Add first element
    cy.get('[data-testid="add-element-button"]').click();
    cy.get('[data-testid="added-manually-button"]').should('be.visible');
    cy.get('[data-testid="added-manually-button"]').should('have.length', 1);

    // Add second element
    cy.get('[data-testid="add-element-button"]').click();
    cy.get('[data-testid="added-manually-button"]').should('have.length', 2);

    // Delete first element
    cy.get('[data-testid="added-manually-button"]').eq(0).click();
    cy.get('[data-testid="added-manually-button"]').should('have.length', 1);

    // Verify remaining element is still visible
    cy.get('[data-testid="added-manually-button"]').should('be.visible');
    cy.get('[data-testid="added-manually-button"]').should('contain', 'Delete');

    // Delete second element
    cy.get('[data-testid="added-manually-button"]').should('have.length', 1);
    cy.get('[data-testid="added-manually-button"]').eq(0).click();
    cy.get('[data-testid="added-manually-button"]').should('not.exist');

    // Verify no elements remain
    cy.get('[data-testid="added-manually-button"]').should('not.exist');
  });

  it('should handle multiple deletions and edge cases', () => {
    // Add three elements
    cy.get('[data-testid="add-element-button"]').click();
    cy.get('[data-testid="added-manually-button"]').should('have.length', 1);
    cy.get('[data-testid="add-element-button"]').click();
    cy.get('[data-testid="added-manually-button"]').should('have.length', 2);
    cy.get('[data-testid="add-element-button"]').click();
    cy.get('[data-testid="added-manually-button"]').should('have.length', 3);

    // Delete first element
    cy.get('[data-testid="added-manually-button"]').eq(0).click();
    cy.get('[data-testid="added-manually-button"]').should('have.length', 2);

    // Delete last element
    cy.get('[data-testid="added-manually-button"]').eq(1).click();
    cy.get('[data-testid="added-manually-button"]').should('have.length', 1);

    // Delete remaining element
    cy.get('[data-testid="added-manually-button"]').eq(0).click();
    cy.get('[data-testid="added-manually-button"]').should('not.exist');

    // Attempt to delete when no elements exist (should not throw error)
    cy.get('[data-testid="added-manually-button"]').should('not.exist');
    cy.get('[data-testid="add-element-button"]').click();
    cy.get('[data-testid="added-manually-button"]').should('have.length', 1);
  });
});
